INSERT INTO troubleshooting (machine_id, problem, symptoms, possible_cause, solution, safety_notes, source) VALUES (65, 'Sleeve placket tidak terlipat atau terbentuk dengan benar', 'Lipatan sleeve placket tidak rapi, lebar lipatan tidak konsisten, atau posisi lipatan bergeser.', 'Tekanan vacuum tidak stabil, posisi kain tidak tepat, area folding kotor, atau parameter folding tidak sesuai ukuran sleeve placket.', 'Periksa sistem vacuum dan kebersihan area folding, pastikan kain diposisikan sesuai tanda alignment, lalu periksa kembali parameter folding untuk lebar 15–30 mm.', 'Matikan mesin dan lepaskan sumber udara sebelum membersihkan atau melakukan penyetelan pada area mekanisme folding.', 'Panduan troubleshooting berdasarkan spesifikasi MAICA UAM-04');
INSERT INTO troubleshooting (machine_id, problem, symptoms, possible_cause, solution, safety_notes, source) VALUES (65, 'Jahitan sleeve placket tidak terbentuk dengan benar', 'Jahitan tidak rapi, jarak jahitan tidak konsisten, atau hasil jahitan tidak sesuai pola.', 'Jarum atau benang tidak terpasang dengan benar, parameter jahitan tidak sesuai, atau mekanisme jahit mengalami gangguan.', 'Periksa pemasangan jarum dan jalur benang, periksa parameter jahitan, lalu lakukan uji jahit sebelum produksi dilanjutkan.', 'Matikan mesin sebelum mengganti jarum, memasang benang, atau melakukan pemeriksaan pada mekanisme jahit.', 'Panduan troubleshooting berdasarkan spesifikasi MAICA UAM-04');
INSERT INTO troubleshooting (machine_id, problem, symptoms, possible_cause, solution, safety_notes, source) VALUES (65, 'Tekanan udara pneumatik tidak mencukupi', 'Folding, penjepitan, atau gerakan aktuator pneumatik berjalan lambat atau tidak selesai.', 'Tekanan supply udara kurang dari kebutuhan 7 bar, kebocoran pada selang atau fitting, atau filter/regulator bermasalah.', 'Periksa tekanan supply dan atur sesuai kebutuhan mesin sekitar 7 bar, periksa kebocoran, serta bersihkan atau periksa filter dan regulator.', 'Tutup supply udara dan buang tekanan sisa sebelum memperbaiki selang, fitting, atau komponen pneumatik.', 'Panduan troubleshooting berdasarkan spesifikasi MAICA UAM-04');
INSERT INTO troubleshooting (machine_id, problem, symptoms, possible_cause, solution, safety_notes, source) VALUES (65, 'Sistem vacuum tidak bekerja dengan baik', 'Kain tidak tertahan dengan kuat saat proses folding atau posisi kain berubah selama proses.', 'Vacuum lemah, saluran vacuum tersumbat, kebocoran pada selang, atau permukaan vacuum kotor.', 'Periksa kekuatan vacuum, bersihkan saluran dan permukaan vacuum, serta periksa selang dan sambungan dari kebocoran.', 'Matikan mesin sebelum membersihkan sistem vacuum dan jangan memasukkan tangan ke area mekanisme saat mesin aktif.', 'Panduan troubleshooting berdasarkan spesifikasi MAICA UAM-04');
INSERT INTO troubleshooting (machine_id, problem, symptoms, possible_cause, solution, safety_notes, source) VALUES (65, 'Laser alignment tidak sesuai dengan posisi kain', 'Garis laser tidak bertepatan dengan posisi sleeve placket sehingga hasil pemasangan atau jahitan bergeser.', 'Posisi referensi laser berubah, area laser kotor, atau posisi kain tidak sesuai dengan titik referensi mesin.', 'Bersihkan area laser, periksa posisi referensi, pastikan kain ditempatkan sesuai tanda alignment, lalu lakukan kalibrasi atau penyetelan sesuai prosedur mesin.', 'Hindari melihat langsung ke sumber laser dan lakukan penyetelan dengan mesin dalam kondisi aman.', 'Panduan troubleshooting berdasarkan spesifikasi MAICA UAM-04');
INSERT INTO troubleshooting (machine_id, problem, symptoms, possible_cause, solution, safety_notes, source) VALUES (65, 'Ukuran sleeve placket tidak sesuai program', 'Lebar atau panjang hasil sleeve placket tidak sesuai ukuran yang ditentukan.', 'Parameter ukuran salah, program tidak sesuai produk, atau posisi kain sebelum proses tidak tepat.', 'Periksa program dan parameter ukuran, pastikan lebar sleeve placket berada dalam rentang 15–30 mm dan panjang tidak melebihi 180 mm, kemudian lakukan sampel uji.', 'Pastikan mesin berhenti sebelum mengubah parameter atau melakukan pengaturan mekanisme.', 'Panduan troubleshooting berdasarkan spesifikasi MAICA UAM-04');
INSERT INTO troubleshooting (machine_id, problem, symptoms, possible_cause, solution, safety_notes, source) VALUES (65, 'Stacker otomatis tidak bekerja atau hasil tidak tertumpuk dengan benar', 'Hasil proses tidak berpindah ke stacker, tumpukan miring, atau salah satu dari dua stacker tidak bekerja.', 'Sensor stacker terganggu, posisi hasil tidak tepat, aktuator pneumatik bermasalah, atau program stacking tidak sesuai.', 'Periksa sensor dan area stacking, pastikan tidak ada benda yang menghalangi mekanisme, periksa supply udara, dan periksa pengaturan program stacking.', 'Jangan memasukkan tangan ke area stacker saat mesin berada dalam siklus otomatis.', 'Panduan troubleshooting berdasarkan spesifikasi MAICA UAM-04');
INSERT INTO troubleshooting (machine_id, problem, symptoms, possible_cause, solution, safety_notes, source) VALUES (65, 'Mesin berhenti di tengah siklus otomatis', 'Proses sleeve placket berhenti sebelum selesai atau sistem kontrol menghentikan siklus.', 'Gangguan sensor, tekanan udara atau vacuum tidak mencukupi, kesalahan program, interlock aktif, atau gangguan sistem kontrol komputer.', 'Periksa pesan kesalahan pada sistem kontrol, periksa tekanan udara dan vacuum, pastikan sensor serta area kerja bebas hambatan, kemudian ulangi siklus setelah penyebab gangguan diperbaiki.', 'Jangan menonaktifkan sensor atau interlock keselamatan. Matikan mesin sebelum melakukan pemeriksaan pada bagian bergerak.', 'Panduan troubleshooting berdasarkan spesifikasi MAICA UAM-04');
